<script setup>
import { ref } from 'vue'
import { ElMessage,ElMessageBox } from 'element-plus'
import { call } from '../api.js'
const props=defineProps({roles:Array})
const emit=defineEmits(['saved','error'])
const open=ref(false),busy=ref(false),form=ref({}),editing=ref(false)
const permissions=[['player:read','查询玩家'],['game:read','查询历史对局'],['dashboard:read','数据看板'],['config:read','查看规则'],['config:write','编辑规则'],['config:publish','发布规则'],['config:rollback','回滚规则'],['character:read','查看生效人物'],['character:draft','查看人物草稿'],['character:write','编辑上传人物'],['character:publish','发布人物'],['character:rollback','回滚人物'],['audio:read','查看生效音频'],['audio:draft','查看音频草稿'],['audio:write','编辑上传音频'],['audio:publish','发布音频'],['audio:rollback','回滚音频'],['release:read','查看审批'],['release:submit','提交审批'],['release:approve','审核发布'],['media:manage','素材清理与恢复'],['audit:read','操作审计']]
function edit(role){editing.value=!!role;form.value=role?{...role,permissions:[...role.permissions],expectedVersion:role.version}:{id:'CUSTOM_',name:'',description:'',permissions:[]};open.value=true}
async function save(){if(busy.value)return;if(!/^CUSTOM_[A-Z0-9_]{1,17}$/.test(form.value.id)||!form.value.name.trim()){ElMessage.error('角色标识须为 CUSTOM_ 开头的大写字母、数字或下划线，合计不超过24位；请填写名称');return}try{await ElMessageBox.confirm('保存后会撤销使用此角色账号的全部会话，重新登录后生效。关联的查看权限会自动补齐。','确认角色权限',{type:'warning'})}catch{return}busy.value=true;try{await call('PUT','/admin-api/v1/roles/'+form.value.id,{name:form.value.name,description:form.value.description,permissions:form.value.permissions,expectedVersion:form.value.expectedVersion??null});open.value=false;ElMessage.success('角色已保存');emit('saved')}catch(e){emit('error',e)}finally{busy.value=false}}
</script>
<template><section class="surface"><div class="surface-heading"><h3>自定义角色</h3><el-button type="primary" @click="edit(null)">新增角色</el-button></div><p class="muted">按模块组合权限；系统固定角色不可修改。账号与全局会话管理保留给超级管理员，自定义角色不具备这些能力。</p><div class="ops-role-actions"><el-button v-for="role in roles?.filter(r=>!r.builtin)" :key="role.id" @click="edit(role)">编辑 {{role.name}}</el-button></div></section><el-drawer v-model="open" :title="editing?'修改自定义角色':'新增自定义角色'" size="min(600px,96vw)" :close-on-click-modal="!busy" :close-on-press-escape="!busy" :show-close="!busy"><el-form label-position="top"><el-form-item label="角色标识"><el-input v-model="form.id" :disabled="editing||busy" maxlength="24" /></el-form-item><el-form-item label="角色名称"><el-input v-model="form.name" maxlength="32" :disabled="busy" /></el-form-item><el-form-item label="职责说明"><el-input v-model="form.description" maxlength="200" :disabled="busy" /></el-form-item><el-form-item label="权限组合"><el-checkbox-group v-model="form.permissions" :disabled="busy"><el-checkbox v-for="[id,label] in permissions" :key="id" :value="id">{{label}}</el-checkbox></el-checkbox-group></el-form-item></el-form><el-button type="primary" :loading="busy" @click="save">核对影响并保存</el-button></el-drawer></template>
